<?php
namespace App\Domain\Workplan\Models;
use App\Enums\WorkplanProgressStatus; use App\Models\Concerns\HasMdaScope; use App\Models\User; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\HasMany;
class WorkplanProgressReport extends Model { use HasMdaScope; protected $fillable=['mda_id','workplan_id','workplan_activity_id','period','status','reported_expenditure','achievement_summary','challenges','corrective_action','next_period_action','remarks','prepared_by','submitted_by','submitted_at','verified_by','verified_at','returned_by','returned_at','return_reason','summary']; protected function casts():array{return ['period'=>\App\Enums\WorkplanTargetPeriod::class,'status'=>WorkplanProgressStatus::class,'reported_expenditure'=>'decimal:2','submitted_at'=>'datetime','verified_at'=>'datetime','returned_at'=>'datetime','summary'=>'array'];} public function workplan():BelongsTo{return $this->belongsTo(Workplan::class);} public function activity():BelongsTo{return $this->belongsTo(WorkplanActivity::class,'workplan_activity_id');} public function indicators():HasMany{return $this->hasMany(WorkplanIndicatorProgress::class);} public function evidence():HasMany{return $this->hasMany(WorkplanEvidence::class);} public function preparedBy():BelongsTo{return $this->belongsTo(User::class,'prepared_by');} public function submittedBy():BelongsTo{return $this->belongsTo(User::class,'submitted_by');} public function verifiedBy():BelongsTo{return $this->belongsTo(User::class,'verified_by');} public function returnedBy():BelongsTo{return $this->belongsTo(User::class,'returned_by');} }
